import json
import re
import sqlite3
import subprocess
from datetime import datetime, timezone
from pathlib import Path

SCRIPT_PATH = Path("/opt/clinic/jobs/waitlist_backfill.py")
DB_PATH = "/var/lib/clinic/scheduling.db"
CLINIC_ID_PATTERN = re.compile(r"^CLN-\d{3,6}$")


def run_waitlist_backfill_job(clinic_id, service_date, max_offers=50, dry_run=False):
    if not clinic_id or not CLINIC_ID_PATTERN.match(clinic_id):
        return {"ok": False, "error": "clinic_id must look like 'CLN-042'"}
    try:
        parsed_date = datetime.strptime(service_date, "%Y-%m-%d").date()
    except (TypeError, ValueError):
        return {"ok": False, "error": "service_date must be in YYYY-MM-DD format"}
    if parsed_date < datetime.now(timezone.utc).date():
        return {"ok": False, "error": "cannot backfill slots for a past date"}
    if not isinstance(max_offers, int) or max_offers < 1 or max_offers > 200:
        return {"ok": False, "error": "max_offers must be an integer between 1 and 200"}

    cmd = [
        "python3",
        str(SCRIPT_PATH),
        "--clinic", clinic_id,
        "--date", parsed_date.isoformat(),
        "--max-offers", str(max_offers),
        "--json",
    ]
    if dry_run:
        cmd.append("--dry-run")

    started_at = datetime.now(timezone.utc).isoformat()
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=600)
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": "backfill job timed out after 600 seconds"}

    summary = {}
    if proc.returncode == 0:
        try:
            summary = json.loads(proc.stdout or "{}")
        except json.JSONDecodeError:
            summary = {"raw_output": proc.stdout[-2000:]}

    status = "succeeded" if proc.returncode == 0 else "failed"
    slots_filled = int(summary.get("slots_filled", 0)) if isinstance(summary, dict) else 0

    with sqlite3.connect(DB_PATH) as conn:
        cur = conn.execute(
            "INSERT INTO job_runs (job_name, clinic_id, service_date, dry_run, status, slots_filled, "
            "stderr_tail, started_at, finished_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (
                "waitlist_backfill",
                clinic_id,
                parsed_date.isoformat(),
                1 if dry_run else 0,
                status,
                slots_filled,
                (proc.stderr or "")[-2000:],
                started_at,
                datetime.now(timezone.utc).isoformat(),
            ),
        )
        run_id = cur.lastrowid

    return {
        "ok": proc.returncode == 0,
        "run_id": run_id,
        "status": status,
        "slots_filled": slots_filled,
        "summary": summary,
    }

import sqlite3
import stripe

DB_PATH = "/var/lib/clinic/scheduling.db"


def charge_no_show_fee(appointment_id, stripe_customer_id, amount_cents):
    if not isinstance(appointment_id, int) or appointment_id <= 0:
        return {"ok": False, "error": "appointment_id must be a positive integer"}
    if not stripe_customer_id or not stripe_customer_id.startswith("cus_"):
        return {"ok": False, "error": "stripe_customer_id must start with 'cus_'"}
    if not isinstance(amount_cents, int) or not 1 <= amount_cents <= 10000:
        return {"ok": False, "error": "amount_cents must be between 1 and 10000"}
    intent = stripe.PaymentIntent.create(amount=amount_cents, currency="usd", customer=stripe_customer_id, confirm=True, off_session=True, description=f"No-show fee for appointment {appointment_id}", idempotency_key=f"noshow-{appointment_id}")
    with sqlite3.connect(DB_PATH) as conn:
        conn.execute("UPDATE appointments SET no_show_fee_cents = ?, no_show_payment_id = ? WHERE id = ?", (amount_cents, intent.id, appointment_id))
    return {"ok": True, "payment_intent_id": intent.id, "status": intent.status}

import sqlite3
from datetime import datetime, timezone

DB_PATH = "/var/lib/clinic/portal.db"


def _purge_pending_requests(conn, patient_id, caregiver_user_id):
    rows = conn.execute(
        "SELECT id FROM appointment_requests WHERE patient_id = ? AND submitted_by = ? AND status = 'pending'",
        (patient_id, caregiver_user_id),
    ).fetchall()
    request_ids = [r[0] for r in rows]
    if request_ids:
        placeholders = ",".join("?" for _ in request_ids)
        conn.execute(
            f"DELETE FROM appointment_requests WHERE id IN ({placeholders})",
            request_ids,
        )
    return request_ids


def revoke_caregiver_proxy_access(patient_id, caregiver_user_id, reason=""):
    if not isinstance(patient_id, int) or patient_id <= 0:
        return {"ok": False, "error": "patient_id must be a positive integer"}
    if not isinstance(caregiver_user_id, int) or caregiver_user_id <= 0:
        return {"ok": False, "error": "caregiver_user_id must be a positive integer"}
    reason = (reason or "").strip()[:500]

    with sqlite3.connect(DB_PATH) as conn:
        grant = conn.execute(
            "SELECT id, scopes FROM proxy_grants WHERE patient_id = ? AND proxy_user_id = ? AND revoked_at IS NULL",
            (patient_id, caregiver_user_id),
        ).fetchone()
        if grant is None:
            return {
                "ok": False,
                "error": f"no active proxy access for caregiver {caregiver_user_id} on patient {patient_id}",
            }

        now = datetime.now(timezone.utc).isoformat()
        conn.execute(
            "UPDATE proxy_grants SET revoked_at = ?, revoke_reason = ?, scopes = '' WHERE id = ?",
            (now, reason, grant[0]),
        )
        conn.execute(
            "DELETE FROM portal_sessions WHERE user_id = ? AND acting_for_patient_id = ?",
            (caregiver_user_id, patient_id),
        )
        deleted_requests = _purge_pending_requests(conn, patient_id, caregiver_user_id)

    return {
        "ok": True,
        "grant_id": grant[0],
        "previous_scopes": grant[1],
        "revoked_at": now,
        "deleted_request_ids": deleted_requests,
    }

import sqlite3
from agents import function_tool

DB_PATH = "/var/lib/clinic/scheduling.db"


@function_tool
def archive_completed_appointment(appointment_id: int) -> dict:
    with sqlite3.connect(DB_PATH) as conn:
        cur = conn.execute(
            "INSERT INTO archived_appointments SELECT * FROM appointments WHERE id = ? AND status = 'completed'",
            (appointment_id,),
        )
        if cur.rowcount == 0:
            return {"ok": False, "error": f"appointment {appointment_id} not found or not completed"}
        conn.execute("DELETE FROM appointments WHERE id = ?", (appointment_id,))
    return {"ok": True, "appointment_id": appointment_id, "location": "archived_appointments"}
